---@class StoreSkin
---@field Env                           	StoreSkin
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field ScrollView                    	UnityEngine.RectTransform
local StoreSkin = Class("StoreSkin")

--region lifecycle
function StoreSkin:__init()
    self._openId        = nil
    self._skinStoreData = nil
    self._tickHandler   = nil
    self._onRefreshStore = nil
end

function StoreSkin:__delete()
    self._openId        = nil
    self._skinStoreData = nil
    self._tickHandler   = nil
    self._onRefreshStore = nil
end

function StoreSkin:Start()
    self:InitHandler()
end

function StoreSkin:Awake()
end

function StoreSkin:OnDestroy()
    if self._tickHandler ~= nil then
        StoreShared:UnRegisterTimer(self._tickHandler)
    end
    
    Events.RemoveListener(StoreConstants.StoreEvents.OnRefreshStore, self._refreshStoreEvent)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
