--region inheritance
--endregion inheritance

--region init
function StoreSkin:InitHandler()
    self._tickHandler = Bind(self, self.OnTimeTick)
    StoreShared:RegisterTimer(self._tickHandler)

    self._refreshStoreEvent = Events.AddListener(StoreConstants.StoreEvents.OnRefreshStore, Bind(self, self.RefreshStoreEventHandler))
end

function StoreSkin:InitData()
    local comp = StoreUtils.GetStoreComp()
    local dataKey = StoreConstants.Config[self._openId].dataKey
    self._skinStoreData = comp.AllStores[dataKey]
end
--endregion init

--region handler
---列表刷新
function StoreSkin:OnGetItemByIndex(listView, index)
    local data = self._skinStoreData[index + 1]
    local cell = listView:NewListViewItem("Cell")
    local cellEnv = CfUtils.GetLuaScr(cell.gameObject, SkinCellLuaPath)
    cellEnv:RefreshCell(self._openId, data) 
    return cell
end

---定时器回调
function StoreSkin:OnTimeTick()
    local refresh = false
    for i, v in pairs(checkTable(self._skinStoreData)) do
        if v.nextRefreshLeftSeconds == 0 then
            refresh = true
            break ;
        end
    end

    if refresh then
        GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                StoreUtils.RefreshStore(response.data)
            end
        end)
        return
    end
    -- 刷新cell
    for i, v in ipairs(self._skinStoreData) do
        if v.nextRefreshLeftSeconds > 0 then
            local go = self.ScrollView:GetShownItemByItemIndex(i - 1)
            if not isNull(go) then
                local scr = CfUtils.GetLuaScr(go, SkinCellLuaPath)
                scr:RefreshTimeGroup(v)
            end
        end
    end
end

---商城刷新事件处理
function StoreSkin:RefreshStoreEventHandler()
    self:InitData()
    self:RefreshView()
end
--endregion handler

--region public
---刷新自身
function StoreSkin:RefreshSelf(params)
    self._openId = params.openId
    self:InitData()
    self:RefreshView()
end
--endregion public

--region private
function StoreSkin:RefreshView()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#self._skinStoreData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #self._skinStoreData)
    end
end
--endregion private

return StoreSkin